package hmgapi.hook; import java.util.*; public class ModContext { public boolean on=true; public Map<String,Boolean> settings=new HashMap<String,Boolean>(); public List<String> logs=new ArrayList<String>(); public Map<String,MethodHook> hooks=new HashMap<String,MethodHook>(); public boolean enabled(){return on;} public boolean settingBoolean(String n,boolean d){return settings.containsKey(n)?settings.get(n):d;} public void log(String s){logs.add(s);} public void hook(ClassLoader c,String s,MethodHook h){hooks.put(s,h);} }
